// Generated by vibelang from src/docs/remark-links.ts; the migrate flow writes it again with each batch.
export default function remarkDocsLinks(options) {
    const docsBase = `${options.base.replace(/\/$/, "")}/docs`;
    return (tree) => {
        const visit = (node) => {
            if (node.type === "link" && node.url?.startsWith("/"))
                node.url = `${docsBase}${node.url}`;
            node.children?.forEach(visit);
        };
        visit(tree);
    };
}
